from pathlib import Path
import re

def replace_between(text, start, end, replacement, label):
    a=text.find(start)
    if a < 0: raise RuntimeError(f"{label}: start marker not found: {start}")
    if end is None: return text[:a] + replacement
    b=text.find(end,a)
    if b < 0: raise RuntimeError(f"{label}: end marker not found: {end}")
    return text[:a] + replacement + text[b:]

def replace_once(text, old, new, label):
    if text.count(old) != 1: raise RuntimeError(f"{label}: expected one occurrence, found {text.count(old)}")
    return text.replace(old,new,1)

