Path('tests/bundle-safety.test.js').write_text("import test from 'node:test';\nimport assert from 'node:assert/strict';\nimport { createNpcRecord } from '../core.js';\nimport { decodeNpcStateBundle, encodeNpcStateBundle, mergeImportedDossierState } from '../bundle.js';\n\nfunction graphEdge(a,b) { return { version:1, edges:[{aId:a,bId:b,aToB:'friend',bToA:'friend'}], unresolved:[] }; }\n\ntest('capacity policy preserves every existing active dossier and skips only new active imports', () => {\n  const a=createNpcRecord('A'); const b=createNpcRecord('B',[a.id]); const c=createNpcRecord('C',[a.id,b.id]);\n  const report={};\n  const merged=mergeImportedDossierState({npcs:[a,b],dismissed:[]},{npcs:[c],dismissed:[]},{maxNpcs:2,report});\n  assert.deepEqual(merged.npcs.map(n=>n.name),['A','B']);\n  assert.equal(report.skipped.length,1);\n  assert.equal(report.skipped[0].reason,'capacity');\n});\n\ntest('matching existing dossier updates in place even when active roster is full', () => {\n  const a=createNpcRecord('A'); a.mood='old'; const b=createNpcRecord('B',[a.id]);\n  const incoming=structuredClone(a); incoming.id='import-a'; incoming.mood='new';\n  const report={};\n  const merged=mergeImportedDossierState({npcs:[a,b],dismissed:[]},{npcs:[incoming],dismissed:[]},{maxNpcs:2,report});\n  assert.deepEqual(merged.npcs.map(n=>n.name),['A','B']);\n  assert.equal(merged.npcs[0].id,a.id);\n  assert.equal(merged.npcs[0].mood,'new');\n  assert.equal(report.updated.length,1);\n});\n\ntest('unrelated imported stable-id collision is reminted and social graph follows the remap', () => {\n  const brina=createNpcRecord('Brina'); brina.id='npc_shared';\n  const maren=createNpcRecord('Maren'); maren.id='npc_shared';\n  const talia=createNpcRecord('Talia',['npc_shared']); talia.id='npc_talia';\n  const report={};\n  const merged=mergeImportedDossierState({npcs:[brina],dismissed:[],socialGraph:{edges:[],unresolved:[]}},{\n    npcs:[maren,talia], dismissed:[], socialGraph:graphEdge('npc_shared','npc_talia')\n  },{maxNpcs:5,report});\n  const savedMaren=merged.npcs.find(n=>n.name==='Maren');\n  assert.ok(savedMaren);\n  assert.notEqual(savedMaren.id,'npc_shared');\n  assert.equal(new Set(merged.npcs.map(n=>n.id)).size, merged.npcs.length);\n  assert.ok(merged.socialGraph.edges.some(e => [e.aId,e.bId].includes(savedMaren.id) && [e.aId,e.bId].includes('npc_talia')));\n  assert.ok(report.idRemaps.some(x=>x.from==='npc_shared' && x.to===savedMaren.id && x.reason==='id-collision'));\n});\n\ntest('ambiguous shared alias cannot merge an imported identity into an arbitrary existing dossier', () => {\n  const a=createNpcRecord('Arlen'); a.aliases=['Captain'];\n  const b=createNpcRecord('Bren'); b.aliases=['Captain'];\n  const incoming=createNpcRecord('Captain',[a.id,b.id]); incoming.id='npc_import_captain';\n  const merged=mergeImportedDossierState({npcs:[a,b],dismissed:[]},{npcs:[incoming],dismissed:[]},{maxNpcs:3});\n  assert.equal(merged.npcs.length,3);\n  assert.ok(merged.npcs.some(n=>n.id==='npc_import_captain' && n.name==='Captain'));\n});\n\ntest('a unique alias remains eligible for conservative import matching', () => {\n  const a=createNpcRecord('Mina Vale'); a.aliases=['Thunderbird'];\n  const incoming=createNpcRecord('Thunderbird'); incoming.id='old-id'; incoming.mood='awake';\n  const merged=mergeImportedDossierState({npcs:[a],dismissed:[]},{npcs:[incoming],dismissed:[]},{maxNpcs:3});\n  assert.equal(merged.npcs.length,1);\n  assert.equal(merged.npcs[0].id,a.id);\n  assert.equal(merged.npcs[0].mood,'awake');\n});\n\ntest('capacity-rejected import cannot leak graph edges onto an existing id collision', () => {\n  const existing=createNpcRecord('Existing'); existing.id='npc_collision';\n  const other=createNpcRecord('Other'); other.id='npc_other';\n  const rejected=createNpcRecord('Rejected'); rejected.id='npc_collision';\n  const importedFriend=createNpcRecord('Friend'); importedFriend.id='npc_friend';\n  const report={};\n  const merged=mergeImportedDossierState({npcs:[existing,other],dismissed:[],socialGraph:{edges:[],unresolved:[]}},{\n    npcs:[rejected,importedFriend], dismissed:[], socialGraph:graphEdge('npc_collision','npc_friend')\n  },{maxNpcs:2,report});\n  assert.equal(merged.npcs.length,2);\n  assert.equal(merged.socialGraph.edges.length,0);\n  assert.equal(report.skipped.filter(x=>x.reason==='capacity').length,2);\n});\n\ntest('decoder rejects duplicate ids inside one bundle', () => {\n  const a=createNpcRecord('A'); const b=createNpcRecord('B'); b.id=a.id;\n  const bytes=encodeNpcStateBundle({npcs:[a,b],dismissed:[]});\n  assert.throws(()=>decodeNpcStateBundle(bytes),/duplicate NPC id/i);\n});\n\ntest('second imported copy of the same identity is skipped instead of creating a duplicate dossier', () => {\n  const existing=createNpcRecord('Mina'); existing.mood='old';\n  const first=createNpcRecord('Mina'); first.id='import_mina_1'; first.mood='first';\n  const second=createNpcRecord('Mina'); second.id='import_mina_2'; second.mood='second';\n  const report={};\n  const merged=mergeImportedDossierState({npcs:[existing],dismissed:[]},{npcs:[first,second],dismissed:[]},{maxNpcs:5,report});\n  assert.equal(merged.npcs.length,1);\n  assert.equal(merged.npcs[0].id,existing.id);\n  assert.equal(merged.npcs[0].mood,'first');\n  assert.equal(report.skipped.filter(x=>x.reason==='duplicate-identity').length,1);\n});\n\ntest('decoder rejects overlapping portrait binary ranges', () => {\n  const a=createNpcRecord('A');\n  const b=createNpcRecord('B');\n  a.portrait={dataUrl:`data:image/webp;base64,${Buffer.from([1,2,3,4]).toString('base64')}`,mime:'image/webp'};\n  b.portrait={dataUrl:`data:image/webp;base64,${Buffer.from([5,6,7,8]).toString('base64')}`,mime:'image/webp'};\n  const bytes=encodeNpcStateBundle({npcs:[a,b],dismissed:[]});\n  const manifestLength=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength).getUint32(8,true);\n  const manifestStart=12;\n  const binaryStart=manifestStart+manifestLength;\n  const manifest=JSON.parse(new TextDecoder().decode(bytes.subarray(manifestStart,binaryStart)));\n  assert.equal(manifest.state.npcs[0].portrait.binary.offset,0);\n  assert.equal(manifest.state.npcs[1].portrait.binary.offset,4);\n  manifest.state.npcs[1].portrait.binary.offset=0;\n  const replacement=new TextEncoder().encode(JSON.stringify(manifest));\n  assert.equal(replacement.length,manifestLength,'fixture mutation must preserve manifest byte length');\n  const corrupt=bytes.slice();\n  corrupt.set(replacement,manifestStart);\n  assert.throws(()=>decodeNpcStateBundle(corrupt),/overlapping portrait data/i);\n});\n\ntest('imported tombstoned stable id is not collapsed into a different current homonym', () => {\n  const current=createNpcRecord('Mina'); current.id='npc_new_mina';\n  const incoming=createNpcRecord('Mina'); incoming.id='npc_old_mina';\n  const report={};\n  const merged=mergeImportedDossierState({\n    npcs:[current], dismissed:[], userDismissedGroups:[{primary:'mina',labels:['mina'],ids:['npc_old_mina'],createdAt:1}]\n  },{npcs:[incoming],dismissed:[]},{maxNpcs:3,report});\n  assert.equal(merged.npcs.length,2);\n  assert.ok(merged.npcs.some(n=>n.id==='npc_new_mina'));\n  assert.ok(merged.npcs.some(n=>n.id==='npc_old_mina'));\n  assert.equal(report.added.length,1);\n});\n")
Path('tests/branch-safety.test.js').write_text("import test from 'node:test';\nimport assert from 'node:assert/strict';\nimport { createNpcRecord } from '../core.js';\nimport {\n  addUserDismissedGroup, bestAncestorState, chatLineage, clearUserDismissedGroupsFor, normalizeUserDismissedGroups,\n  preserveUserNpcMetadata, promoteLegacyUserDismissedGroups, recordBranchCheckpoint, reconcileBranchState\n} from '../branch.js';\n\nfunction user(text){return {is_user:true,is_system:false,name:'User',mes:text};}\nfunction assistant(text){return {is_user:false,is_system:false,name:'AI',mes:text};}\nfunction baseState(){return {npcs:[],candidates:[],pendingBackfills:[],dismissed:[],inlineCards:[],checkpoints:[],lineage:[],branchLineageVersion:2,socialGraph:{edges:[],unresolved:[]},turn:0,assistantSinceScan:0,lastScanAt:0,lastScannedMessageId:null,scanCount:0,processedOocMessageId:null,userDismissedGroups:[]};}\n\ntest('modern permanent deletion tombstone is id-based and does not erase a different homonym',()=>{\n  const chat=[user('start'),assistant('later')];\n  const state=baseState();\n  const deleted=createNpcRecord('Mina'); deleted.id='npc_old_mina';\n  const homonym=createNpcRecord('Mina'); homonym.id='npc_new_mina';\n  state.npcs=[deleted,homonym];\n  state.lineage=chatLineage([user('different')]);\n  state.userDismissedGroups=addUserDismissedGroup([],deleted);\n  const result=reconcileBranchState(state,chat,{explicitDivergence:0});\n  assert.deepEqual(result.state.npcs.map(n=>n.id),['npc_new_mina']);\n  assert.equal(result.state.dismissed.includes('mina'),false);\n});\n\ntest('historical ids can be attached to one deletion tombstone for old branch snapshots',()=>{\n  const deleted=createNpcRecord('Mina'); deleted.id='npc_current';\n  const groups=addUserDismissedGroup([],deleted,{historicalNpcIds:['npc_interim']});\n  assert.deepEqual(normalizeUserDismissedGroups(groups)[0].ids.sort(),['npc_current','npc_interim']);\n});\n\ntest('legacy label-only deletion groups retain legacy suppression behavior',()=>{\n  const chat=[user('start')];\n  const state=baseState();\n  state.npcs=[Object.assign(createNpcRecord('Mina'),{id:'npc_any'})];\n  state.lineage=chatLineage([user('other')]);\n  state.userDismissedGroups=[{primary:'mina',labels:['mina'],createdAt:1}];\n  const result=reconcileBranchState(state,chat,{explicitDivergence:0});\n  assert.equal(result.state.npcs.length,0);\n  assert.ok(result.state.dismissed.includes('mina'));\n});\n\ntest('new branch can inherit a verified message-zero checkpoint from a one-message common prefix',()=>{\n  const shared=user('Shared opening');\n  const parentChat=[shared,assistant('Parent continuation')];\n  const parent=baseState();\n  parent.npcs=[createNpcRecord('Mina')];\n  recordBranchCheckpoint(parent,parentChat,0,'opening');\n  const childChat=[shared,assistant('Different continuation')];\n  const inherited=bestAncestorState({'chat:parent':parent},'chat:child',childChat);\n  assert.ok(inherited);\n  assert.equal(inherited.branchForkMessageId,0);\n  assert.equal(inherited.npcs[0].name,'Mina');\n});\n\n\ntest('branch metadata restore prefers exact id and refuses ambiguous homonym label fallback',()=>{\n  const original=[user('Shared'),assistant('Scene A')];\n  const state=baseState();\n  const oldMina=createNpcRecord('Mina'); oldMina.id='npc_old'; oldMina.importance=99; oldMina.retentionProtected=true;\n  const newMina=createNpcRecord('Mina'); newMina.id='npc_new'; newMina.importance=20; newMina.retentionProtected=false;\n  state.npcs=[oldMina,newMina];\n  recordBranchCheckpoint(state,original,0,'rootish');\n  const checkpoint=state.checkpoints.find(x=>x.messageId===0);\n  checkpoint.snapshot.npcs=[structuredClone(newMina)];\n  const changed=[user('Shared'),assistant('Scene B')];\n  const result=reconcileBranchState(state,changed,{explicitDivergence:1});\n  const restored=result.state.npcs.find(n=>n.id==='npc_new');\n  assert.equal(restored.importance,20);\n  assert.equal(restored.retentionProtected,false);\n});\n\ntest('same-name different-id explicit add/import does not clear a modern deletion tombstone',()=>{\n  const deleted=createNpcRecord('Mina'); deleted.id='npc_old';\n  const groups=addUserDismissedGroup([],deleted);\n  const homonym=createNpcRecord('Mina'); homonym.id='npc_new';\n  const cleared=clearUserDismissedGroupsFor(groups,homonym,{modernByIdOnly:true});\n  assert.equal(cleared.groups.length,1);\n  assert.deepEqual(cleared.removedIds,[]);\n  const resurrected=clearUserDismissedGroupsFor(groups,deleted,{modernByIdOnly:true});\n  assert.equal(resurrected.groups.length,0);\n  assert.deepEqual(resurrected.removedIds,['npc_old']);\n});\n\ntest('metadata restore still supports a unique label fallback when an id legitimately changed',()=>{\n  const restored=createNpcRecord('Mina'); restored.id='npc_old'; restored.importance=10;\n  const current=createNpcRecord('Mina'); current.id='npc_new'; current.importance=77; current.retentionProtected=true;\n  const result=preserveUserNpcMetadata([restored],[current]);\n  assert.equal(result[0].importance,77);\n  assert.equal(result[0].retentionProtected,true);\n});\n\ntest('legacy label tombstone upgrades to an id only when branch history proves one identity',()=>{\n  const old=createNpcRecord('Mina'); old.id='npc_old';\n  const upgraded=promoteLegacyUserDismissedGroups([{primary:'mina',labels:['mina'],createdAt:1}],[[old]]);\n  assert.deepEqual(upgraded[0].ids,['npc_old']);\n  const other=createNpcRecord('Mina'); other.id='npc_other';\n  const ambiguous=promoteLegacyUserDismissedGroups([{primary:'mina',labels:['mina'],createdAt:1}],[[old],[other]]);\n  assert.deepEqual(ambiguous[0].ids,[]);\n});\n\ntest('public name-based tombstone clearing remains backward compatible for explicit legacy/manual callers',()=>{\n  const deleted=createNpcRecord('Mina'); deleted.id='npc_old'; deleted.aliases=['The Innkeeper'];\n  const groups=addUserDismissedGroup([],deleted);\n  const cleared=clearUserDismissedGroupsFor(groups,'Mina');\n  assert.equal(cleared.groups.length,0);\n  assert.ok(cleared.removedIds.includes('npc_old'));\n  assert.ok(cleared.removedLabels.includes('the innkeeper'));\n});\n")
Path('tests/runtime-safety.test.js').write_text("import test from 'node:test';\nimport assert from 'node:assert/strict';\nimport { createScanOperationRegistry, deletedChatStateKey } from '../branch.js';\n\ntest('scan locks are isolated by chat key',()=>{\n  const timers=[];\n  const registry=createScanOperationRegistry({setTimeoutFn:(fn)=>{timers.push(fn); return {unref(){}};},clearTimeoutFn:()=>{}});\n  const a=registry.begin('chat:a','scan');\n  const b=registry.begin('chat:b','scan');\n  assert.ok(a && b);\n  assert.equal(registry.begin('chat:a','other'),null);\n  assert.equal(registry.isBusy('chat:a'),true);\n  assert.equal(registry.isBusy('chat:b'),true);\n  registry.end('chat:a',a);\n  assert.equal(registry.isBusy('chat:a'),false);\n  assert.equal(registry.isBusy('chat:b'),true);\n});\n\ntest('expired scan releases only its own chat and stale operation token is no longer current',()=>{\n  const timers=[]; const expired=[];\n  const registry=createScanOperationRegistry({timeoutMs:1000,onExpire:op=>expired.push(op.key),setTimeoutFn:(fn)=>{timers.push(fn); return {unref(){}};},clearTimeoutFn:()=>{}});\n  const a=registry.begin('chat:a','scan');\n  const b=registry.begin('chat:b','scan');\n  timers[0]();\n  assert.deepEqual(expired,['chat:a']);\n  assert.equal(registry.isBusy('chat:a'),false);\n  assert.equal(registry.isBusy('chat:b'),true);\n  assert.equal(registry.isCurrent('chat:a',a),false);\n  assert.equal(registry.isCurrent('chat:b',b),true);\n});\n\ntest('old operation finally cannot clear a newer operation',()=>{\n  const timers=[];\n  const registry=createScanOperationRegistry({timeoutMs:1000,setTimeoutFn:(fn)=>{timers.push(fn); return {unref(){}};},clearTimeoutFn:()=>{}});\n  const first=registry.begin('chat:a','first');\n  timers[0]();\n  const second=registry.begin('chat:a','second');\n  assert.ok(second);\n  assert.equal(registry.end('chat:a',first),false);\n  assert.equal(registry.isCurrent('chat:a',second),true);\n});\n\ntest('deleted chat storage key is strictly namespaced',()=>{\n  assert.equal(deletedChatStateKey('123.jsonl','chat'),'chat:123');\n  assert.equal(deletedChatStateKey('123','group'),'group:123');\n  assert.equal(deletedChatStateKey('123','other'),'');\n});\n")
Path('tests/index-hardening.test.js').write_text("import test from 'node:test';\nimport assert from 'node:assert/strict';\nimport { readFileSync } from 'node:fs';\n\nconst source=readFileSync(new URL('../index.js',import.meta.url),'utf8');\n\ntest('runtime integration uses per-chat scan operations and no legacy global scanBusy flag',()=>{\n  assert.match(source,/createScanOperationRegistry/);\n  assert.match(source,/beginScanOperation\\(scanChatKey/);\n  assert.match(source,/scanOperationCurrent\\(scanChatKey, operation\\)/);\n  assert.doesNotMatch(source,/\\bscanBusy\\b/);\n});\n\ntest('chat deletion handlers preserve chat/group namespace isolation',()=>{\n  assert.match(source,/removeDeletedChatState\\(chatId, 'chat'\\)/);\n  assert.match(source,/removeDeletedChatState\\(chatId, 'group'\\)/);\n  assert.doesNotMatch(source,/for \\(const key of \\[`chat:\\$\\{id\\}`, `group:\\$\\{id\\}`\\]\\)/);\n});\n\ntest('bundle import reports skipped capacity and only clears deletion state for accepted imports',()=>{\n  assert.match(source,/report: importReport/);\n  assert.match(source,/for \\(const accepted of importReport\\.accepted \\|\\| \\[\\]\\)/);\n  assert.match(source,/existing active dossiers were preserved/);\n});\n\ntest('manual trash removes narrative name suppression and branch inheritance accepts message zero',()=>{\n  assert.match(source,/const permanentLabels = new Set/);\n  assert.match(source,/working\\.dismissed = .*?working\\.dismissed/s);\n  assert.match(source,/chat\\.length < 1/);\n});\n")

